import re
import os
import subprocess

def task_func(dir_path, exe_pattern, execute_files=True):
    pattern = re.compile(exe_pattern)
    results = []

    if not os.path.isdir(dir_path):
        return results

    try:
        entries = list(os.scandir(dir_path))
    except OSError:
        return results

    matched_paths = []
    for entry in sorted(entries, key=lambda e: e.name):
        try:
            if entry.is_file(follow_symlinks=False) and os.access(entry.path, os.X_OK):
                if pattern.fullmatch(entry.name):
                    matched_paths.append(entry.path)
        except OSError:
            continue

    if not execute_files:
        return matched_paths

    for path in matched_paths:
        try:
            completed = subprocess.run(
                [path],
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                check=False,
            )
            results.append(completed.stdout)
        except OSError:
            results.append("")

    return results
